mapper.select:
select ct.id as 'contractId', ct.contract_code as 'contractCode', ct.title as 'title', ct.valid_start_date as 'validStartDate', ct.valid_end_date as 'validEndDate', ct.trade_time as 'tradeTime', ct.contract_date as 'contractDate', ct.creater as 'createrId', ct.create_time as 'createTime', ct.contract_type as 'contractType', ct.document_id as 'documentId', ct.document_code as 'documentCode', ct.document_type as 'documentType', ct.contract_price as 'contractPrice', ct.modifier as 'modifier' , ct.modify_time as 'modifyTime', ct.ver as 'ver', ct.trustor_company_id as 'trustorCompanyId', ct.carrier_company_id as 'carrierCompanyId', ct.agent_company_id as 'agentCompanyId', ct.compile_side_id as 'compileSideCompanyId', ct.contract_template_id as 'contractTemplateId', ct.contract_template_name as 'contractTemplateName', ct.contract_template_business_type as 'businessType', ct.is_delete as 'isDelete', ct.ec_contract_pdf_id as 'ecContractPdfId', ct.ec_contract_result_code as 'ecContractResultCode', ct.ec_contract_result_desc as 'ecContractResultDesc', ct.trustor_sign_status as 'trustorSignStatus', ct.carrier_sign_status as 'carrierSignStatus', ct.agent_sign_status as 'agentSignStatus', ct.ec_contract_create_time as 'ecContractCreateTime', ct.trustor_company_name as 'trustorCompanyName', ct.carrier_company_name as 'carrierCompanyName', ct.agent_company_name as 'agentCompanyName', ct.creater as 'creater', ct.contract_goods_collection as 'contractGoodsCollection', ct.contract_measuring_collection as 'contractMeasuringCollection', p_con.id as 'parentContractId', p_con.contract_code as 'parentContractCode', attach.attachNums as 'attachNumber' FROM settle_bills ct LEFT JOIN settle_bills p_con on ct.parent_contract_id = p_con.id LEFT JOIN (select COUNT(att.id) as attachNums, att.contract_id as attachContractId from contract_attach att GROUP BY att.contract_id) attach on attach.attachContractId = ct.id
IFNULL(ct.is_delete, 0) != 1 and ( ct.trustor_company_id = #{contractListQry.companyId,jdbcType=CHAR} or ct.carrier_company_id = #{contractListQry.companyId,jdbcType=CHAR} or ct.agent_company_id = #{contractListQry.companyId,jdbcType=CHAR} or ct.compile_side_id= #{contractListQry.companyId,jdbcType=CHAR} or ct.plat_company_id = #{contractListQry.companyId,jdbcType=CHAR})
and ct.contract_code = #{contractListQry.contractCode}
and instr(ct.trustor_company_name, #{contractListQry.trustorCompanyName,jdbcType=CHAR})
and instr(ct.carrier_company_name, #{contractListQry.carrierCompanyName,jdbcType=CHAR})
and instr(ct.agent_company_name, #{contractListQry.agentCompanyName,jdbcType=CHAR})
and ((date_format(ct.valid_start_date,'%Y-%m-%d') >= date_format(#{contractListQry.startDate,jdbcType=VARCHAR},'%Y-%m-%d')))
and ((date_format(ct.valid_end_date,'%Y-%m-%d') <= date_format(#{contractListQry.endDate,jdbcType=VARCHAR},'%Y-%m-%d')))
and ((ct.trade_time >= date_format(#{contractListQry.tradeStartTime,jdbcType=VARCHAR},'%Y-%m-%d %H:%i:%S')))
and ((ct.trade_time <= date_format(#{contractListQry.tradeEndTime,jdbcType=VARCHAR},'%Y-%m-%d %H:%i:%S')))
and ct.trustor_sign_status = #{contractListQry.trustorSignStatus,jdbcType=BIGINT}
and ct.carrier_sign_status = #{contractListQry.carrierSignStatus,jdbcType=BIGINT}
and ct.agent_sign_status = #{contractListQry.agentSignStatus,jdbcType=BIGINT}
and ct.contract_type = #{contractListQry.contractType,jdbcType=BIGINT}
and ct.document_type = #{contractListQry.documentType,jdbcType=BIGINT}
and ct.contract_template_business_type = #{contractListQry.businessType,jdbcType=BIGINT}
group by ct.id order by ct.create_time desc

select cont.* from ( select contract_id as contractId, charge_subject_version as chargeSubjectVersion, payment_schedule_version as paymentScheduleVersion, -- settle_subject_id as settleSubjectId, -- settle_subject_name as settleSubjectName, ver as ver FROM contract_charge where contract_id IN
#{ids}
order by ver desc )as con GROUP BY con.contractId

select
ct.id as 'contractId',
ct.contract_code as 'contractCode',
ct.direction ,
ct.contract_template_business_type as 'businessType'
FROM settle_bills ct

    IFNULL(ct.is_delete, 0) != 1
    and ct.contract_type = 2961010
    and ct.valid_start_date  <  #{dispatchTime}
    and ct.valid_end_date  >=  #{dispatchTime}


        and ct.trustor_company_id = #{trustorCompanyId}


        and ct.carrier_company_id = #{carrierCompanyId}


        and ct.agent_company_id = #{agentCompanyId}


        and ct.direction = #{direction,jdbcType=BIGINT}


        and ct.contract_template_business_type = #{contractTemplateBusinessType,jdbcType=BIGINT}
